 dl:{ti:"Planning a barbecue",sp:[["Hana","she"],["Mick","he"]],ln:[[0,"Do we have [[enough sausages]] for twenty people?"],[1,"No, we need more. And is the barbie [[big enough]]?"],[0,"I think so. Is it [[warm enough]] to eat outside?"],[1,"Yes, but it might be [[too windy]]."],[0,"We don't have [[enough chairs]] either."],[1,"I'll ask the neighbours. They're [[kind enough to lend]] us some."]]},
 mc:[["Is your English good ___ for the job?",["enough","too","very"],0,"Adjective + enough."],["We don't have ___ for a holiday.",["money enough","enough money","enough of money"],1,"Enough + noun."],["He's not tall ___ to reach the shelf.",["enough","too","so"],0,"Not + adjective + enough."],["Which sentence is correct?",["It's enough warm to swim.","It's warm enough to swim.","It's warm to swim enough."],1,"Adjective + enough + to."]],
 bd:[["Is the room big enough",[]],["We don't have enough time",[]]],
 gp:[["Is the tea ___ ? (sweet, enough)",["sweet enough"],"Adjective + enough."],["Do you have ___ for the bus? (money, enough)",["enough money"],"Enough + noun."],["She isn't old ___ to drive yet.",["enough"],"Adjective + enough + to."]],
 pr:"Write about your home or your week. What do you have enough of? What isn't big, quick or warm enough?",
 md:"I don't get enough exercise during the week. My flat isn't big enough for a dining table. But I have enough time on Sundays to walk along the beach.",
