 mc:[["We booked a ___ holiday.",["two-weeks","two-week","two weeks'"],1,"Number modifier: singular and hyphenated."],["I didn't understand ___.",["the film's end","the end of the film","the film end"],1,"For things: the end of."],["I work at a ___.",["shoes shop","shoe shop","shoe's shop"],1,"Noun + noun: first noun singular."],["Which is most natural?",["The company's new CEO","The new CEO of the company of mine","The company new CEO"],0,"Organisations often take 's."]],
 bd:[["We had a two-hour meeting",[]],["The cost of living is high",[]]],
 gp:[["It's a ___ drive to the beach. (20 minutes)",["twenty-minute","20-minute"],"Number modifier: hyphenated, singular."],["I read about it in ___ paper. (today)",["today's"],"Time: today's."],["She opened the door ___ the car. (of or 's)",["of"],"For things: the door of the car (or the car door)."]],
